START TRANSACTION;

CREATE TABLE "PaymentRequests" (
    "PaymentRequestId" integer GENERATED BY DEFAULT AS IDENTITY,
    "InvoiceId" integer NOT NULL,
    "CustomerId" integer NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Currency" character varying(3) NOT NULL,
    "Provider" character varying(32) NOT NULL,
    "OrderCode" bigint NOT NULL,
    "PaymentLinkId" character varying(128),
    "CheckoutUrl" character varying(2048),
    "Status" character varying(32) NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    "UpdatedAtUtc" timestamp with time zone NOT NULL,
    "ExpiresAtUtc" timestamp with time zone,
    "ConfirmedAtUtc" timestamp with time zone,
    "WebhookReceivedAtUtc" timestamp with time zone,
    "ProviderReference" character varying(256),
    "LastErrorCode" character varying(128),
    "LastErrorMessage" character varying(1000),
    "PaymentId" integer,
    CONSTRAINT "PK_PaymentRequests" PRIMARY KEY ("PaymentRequestId"),
    CONSTRAINT "CK_PaymentRequests_Amount_Positive" CHECK ("Amount" > 0),
    CONSTRAINT "CK_PaymentRequests_Currency" CHECK ("Currency" = 'VND'),
    CONSTRAINT "CK_PaymentRequests_ExpiresAt" CHECK ("ExpiresAtUtc" IS NULL OR "ExpiresAtUtc" > "CreatedAtUtc"),
    CONSTRAINT "CK_PaymentRequests_OrderCode_Positive" CHECK ("OrderCode" > 0),
    CONSTRAINT "CK_PaymentRequests_Status" CHECK ("Status" IN ('Creating', 'Pending', 'Succeeded', 'Cancelled', 'Expired', 'Create-failed', 'RequiresReview')),
    CONSTRAINT "CK_PaymentRequests_UpdatedAt" CHECK ("UpdatedAtUtc" >= "CreatedAtUtc"),
    CONSTRAINT "FK_PaymentRequests_Invoices_InvoiceId" FOREIGN KEY ("InvoiceId") REFERENCES "Invoices" ("InvoiceId") ON DELETE RESTRICT,
    CONSTRAINT "FK_PaymentRequests_Payments_PaymentId" FOREIGN KEY ("PaymentId") REFERENCES "Payments" ("PaymentId") ON DELETE RESTRICT,
    CONSTRAINT "FK_PaymentRequests_Users_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Users" ("UserId") ON DELETE RESTRICT
);

CREATE INDEX "IX_PaymentRequests_CustomerId" ON "PaymentRequests" ("CustomerId");

CREATE UNIQUE INDEX "IX_PaymentRequests_OrderCode" ON "PaymentRequests" ("OrderCode");

CREATE UNIQUE INDEX "IX_PaymentRequests_PaymentId" ON "PaymentRequests" ("PaymentId");

CREATE UNIQUE INDEX "IX_PaymentRequests_PaymentLinkId" ON "PaymentRequests" ("PaymentLinkId") WHERE "PaymentLinkId" IS NOT NULL;

CREATE UNIQUE INDEX "UX_PaymentRequests_InvoiceId_Active" ON "PaymentRequests" ("InvoiceId") WHERE "Status" IN ('Creating', 'Pending', 'RequiresReview');

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261110164307_AddInvoicePaymentRequests', '8.0.10');

COMMIT;

